import { pgTable, serial, integer, text, jsonb, timestamp } from "drizzle-orm/pg-core";

// The narrative sections of a TOPIC report (shipping, conflict, fuel, cargo,
// energy, fertiliser, flashpoint/protests/strikes), AI-generated by the topic
// prose engine (artifacts/api-server/src/lib/reportProse.ts). Unlike the country
// brief, every section is a plain string so it maps 1:1 onto the editor's
// textarea form fields and the on-screen/PDF previews — implications and
// watchNext are newline-joined bullet text, the rest are paragraphs. This is the
// SAME shape as TopicReportProse (the deterministic draft) so the AI narrative
// and the deterministic fallback are interchangeable in the editor and renderer.
export interface TopicProseSections {
  executiveSummary: string;
  situation: string;
  whatHappened: string;
  whatMatters: string;
  implications: string;
  watchNext: string;
  polestarView: string;
}

// Cache of AI-generated topic-report prose, keyed one-row-per-report.
//
// `fingerprint` hashes the exact (canonical, capped) incident set the prose was
// grounded on plus the topic, issue date, basis window and prompt version, so
// when the underlying data changes the fingerprint changes and the prose
// regenerates — the cache can never go stale. `edited` holds analyst overrides
// bound to the SAME fingerprint; it is dropped whenever the prose is
// regenerated, so an edit only ever describes the data snapshot it was written
// against. Mirrors report_incident_summaries / country_report_prose.
export const reportProseTable = pgTable("report_prose", {
  id: serial("id").primaryKey(),
  reportId: integer("report_id").notNull().unique(),
  topic: text("topic").notNull(),
  fingerprint: text("fingerprint").notNull(),
  sections: jsonb("sections").$type<TopicProseSections>().notNull(),
  edited: jsonb("edited").$type<TopicProseSections | null>(),
  model: text("model").notNull(),
  generatedAt: timestamp("generated_at", { withTimezone: true }).notNull().defaultNow(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export type ReportProse = typeof reportProseTable.$inferSelect;
export type InsertReportProse = typeof reportProseTable.$inferInsert;
